changeSet.sql:
alter table benutzer_verzeichnis add constraint benutzer_verzeichnis_rolle_ck
    check (rolle in ('INHABER', 'MITARBEITER', 'TREUHAENDER', 'GESCHAEFTSSTELLE', 'API_TOKEN'));
alter table benutzer_verzeichnis add constraint benutzer_verzeichnis_anlass_ck
    check (anlass in ('AKTION', 'AUSTRITT', 'WIDERRUF'));
alter table benutzer_verzeichnis add constraint benutzer_verzeichnis_gueltig_ck
    check (gueltig_bis is null or gueltig_bis >= gueltig_von);
create index benutzer_verzeichnis_benutzer_ix on benutzer_verzeichnis (benutzer, id);
create index zugriff_protokoll_zeit_ix on zugriff_protokoll (zeit);
create index zugriff_protokoll_benutzer_ix on zugriff_protokoll (benutzer, zeit);
create index zugriff_protokoll_dokument_ix on zugriff_protokoll (dokument_id, zeit);

create trigger benutzer_verzeichnis_nur_einfuegen before update or delete on benutzer_verzeichnis
    for each row execute function benutzer_verzeichnis_nur_einfuegen();
create trigger benutzer_verzeichnis_kein_truncate before truncate on benutzer_verzeichnis
    for each statement execute function benutzer_verzeichnis_nur_einfuegen();
